def bubble_passes(a):
    n = len(a); passes = 0; swapped = True
    while swapped:
        swapped = False; passes += 1
        for j in range(n - 1):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]; swapped = True
    return passes
a = [5, 1, 2, 6, 3, 4]
inv = sum(a[i] > a[j] for i in range(6) for j in range(i + 1, 6))
print(bubble_passes(list(a)), inv)   # 3 6

